import{_ as m,h as s,i as e,c as n,v as a,p as i,x as t,m as l,e as f,S as p}from"./chunks/framework.Dvtg8yj2.js";const _=JSON.parse('{"title":"Nyströmformer","description":"","frontmatter":{"title":"Nyströmformer","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/nystromformer.md","filePath":"llm/nystromformer.md","lastUpdated":1788454257000}'),d={name:"llm/nystromformer.md"};function h(A,r,E,c,x,N){const o=s("Mermaid");return e(),n("div",null,[r[1]||(r[1]=a('<h1 id="nystromformer" tabindex="-1">Nyströmformer <a class="header-anchor" href="#nystromformer" aria-label="Permalink to &quot;Nyströmformer&quot;">​</a></h1><div class="epigraph"><p>用少量地标对 softmax 注意力矩阵做 Nyström 重构：近似发生在已经指数化的相似度上，而不是先把键值投影掉再 softmax。</p><footer>—— Xiong et al., Nyströmformer, AAAI 2021</footer></div><p>矩阵 Nyström 方法用若干列（地标）重构一个对称半正定核矩阵。Xiong、Zeng、You、Liu、Ho、Demmel、Keutzer 与 Stoica 把它接到自注意力：不物化 \\(n\\times n\\) 的 \\(S=\\mathrm{softmax}(QK^\\top/\\sqrt{d})\\)，而选 \\(m\\) 个地标，用三块较小的 softmax 与伪逆拼出对 \\(SV\\) 的近似。这与 <a href="/llm/linformer">Linformer</a> 先压长度再 softmax、<a href="/llm/performer-favor">Performer</a> 用随机特征逼近指数核，构成 2020–2021 年「线性注意力」三条常见路中的第三条。本篇写 Nyström 重构作为论文贡献、地标怎么取，以及地标质量如何封顶误差。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>softmax 矩阵 \\(A=\\mathrm{softmax}(QK^\\top/\\sqrt{d})\\) 是注意力的非线性核心：近似若发生在 softmax <em>之前</em>，尖峰可能被投影抹平；若发生在 softmax <em>之后</em>，才是在近似真正进入 \\(AV\\) 的那张行随机矩阵。Nyström 针对后者。经典 Nyström 要求核矩阵对称 PSD；注意力里查询与键来自不同投影，\\(A\\) 甚至不必对称。论文要用地标构造仍可计算的类似物，并处理伪逆的稳定性。</p><p>地标数 \\(m\\ll n\\) 时，复杂度目标是 \\(O(n m d)\\) 量级，与 Linformer 的 \\(k\\)、Performer 的特征维扮演同类旋钮。差别是语义：Linformer 的 \\(k\\) 个槽是长度维混合；Performer 的特征是随机方向；Nyström 的 \\(m\\) 个地标是 <em>序列上的代表位置</em>（或代表段），重构试图保住这些代表所张成的核子空间。</p><h3 id="对-softmax-矩阵做-nystrom" tabindex="-1">对 softmax 矩阵做 Nyström <a class="header-anchor" href="#对-softmax-矩阵做-nystrom" aria-label="Permalink to &quot;对 softmax 矩阵做 Nyström&quot;">​</a></h3><p>标准 Nyström 对核矩阵 \\(K\\) 选指标集 \\(I\\)，\\(|I|=m\\)，用 \\(K_{:,I}K_{I,I}^{+}K_{I,:}\\) 近似 \\(K\\)。注意力需要的是 \\(AV\\)，即近似矩阵右乘 \\(V\\)。把地标写成 \\(\\tilde{Q},\\tilde{K}\\) 后，论文构造由 \\(\\mathrm{softmax}(Q\\tilde{K}^\\top)\\)、地标之间的 softmax、以及 \\(\\mathrm{softmax}(\\tilde{Q}K^\\top)\\) 一类块组成的乘积，中间插 Moore–Penrose 伪逆。细节以原文公式为准；要点是：<strong>指数与行归一化出现在小矩阵上</strong>，大 \\(n\\times n\\) 不物化。</p><p><span class="marginnote">伪逆对小特征值极敏感。地标太共线，地标核接近奇异，重构爆炸。迭代法求伪逆（原文采用的稳定化）不是装饰，是让训练不 NaN 的条件。把 <code>pinv</code> 一句话换成 SVD 截断，截断阈值会变成新超参。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>地标选取是方法的一半。原文常用 <strong>segment-means</strong>：把长度为 \\(n\\) 的序列切成 \\(m\\) 段，段内平均得到地标的 \\(Q/K\\)。这比随机抽 \\(m\\) 个 token 更稳，也比可学习查询少一套与内容无关的参数。平均是低通，段内尖峰会被抹掉——若答案依赖段内某一个稀有 token，该地标可能代表不了它。也可采用均匀下标采样；消融应报告，而不是只报最佳 \\(m\\)。</p><p>得到地标后，按 Nyström 结构计算近似注意力输出，再走标准的输出投影与残差。论文在 GLUE、Long Range Arena、IMDB 等上与满注意力、Linformer、Performer、Reformers 一类基线比：短任务接近 BERT，长程任务看 LRA 分数。LRA 本身有争议，但在 2021 年是把「线性变体」放在同一长度协议下的公共场。</p>',12)),(e(),i(p,null,{default:t(()=>[f(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEQ%5B%22%E9%95%BF%E5%BA%A6%20n%20%E7%9A%84%20Q%2CK%2CV%22%5D%20--%3E%20LM%5B%22%E9%80%89%20m%20%E4%B8%AA%E5%9C%B0%E6%A0%87%20%2F%20%E6%AE%B5%E5%9D%87%E5%80%BC%22%5D%0A%20%20LM%20--%3E%20S1%5B%22%E5%9C%B0%E6%A0%87%E7%9B%B8%E5%85%B3%E7%9A%84%E5%B0%8F%20softmax%20%E5%9D%97%22%5D%0A%20%20SEQ%20--%3E%20S1%0A%20%20S1%20--%3E%20PINV%5B%22%E7%A8%B3%E5%AE%9A%E4%BC%AA%E9%80%86%22%5D%0A%20%20PINV%20--%3E%20OUT%5B%22%E9%87%8D%E6%9E%84%E5%90%8E%E7%9A%84%20AV%22%5D%0A"})]),fallback:t(()=>[...r[0]||(r[0]=[l(" Loading... ",-1)])]),_:1})),r[2]||(r[2]=a('<h3 id="地标与伪逆" tabindex="-1">地标与伪逆 <a class="header-anchor" href="#地标与伪逆" aria-label="Permalink to &quot;地标与伪逆&quot;">​</a></h3><p>段均值地标把「代表点」绑在位置网格上，不依赖内容，便宜、可并行。内容自适应地标（按范数、按聚类）更接近 Routing Transformer 的簇中心，但会引入离散选择，离开原文的默认。伪逆块的尺寸是 \\(m\\times m\\)，应保持很小；\\(m\\) 涨到几百，线性优势消失，数值却更稳——这是精度–费用的同一旋钮。迭代 Moore–Penrose 用矩阵多项式逼近伪逆，避免显式 SVD，更适合当时的框架与混合精度。</p><h3 id="与-linformer、performer-的分工" tabindex="-1">与 Linformer、Performer 的分工 <a class="header-anchor" href="#与-linformer、performer-的分工" aria-label="Permalink to &quot;与 Linformer、Performer 的分工&quot;">​</a></h3><p>Linformer：softmax 的键集合先被 \\(E\\) 混合，近似在非线性之前。Performer：用正随机特征逼近 \\(\\exp(q^\\top k)\\)，期望上对核无偏（对 softmax 行仍有偏）。Nyströmformer：对已 softmax 的结构做列空间重构，地标是确定性的（给定分段）。三者都可能在 LRA 上互有胜负；论文贡献不是「永远最好」，而是给出可训练的 Nyström 注意力层，并配上稳定伪逆。不要把地标数 \\(m\\) 和 Linformer 的 \\(k\\) 当成同一个超参去直接抄数字。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Nyström 误差在地标张成的子空间上小，在正交补上大。若真实注意力的质量集中在少数段（文档里的相关段落），段均值可能碰巧抓住；若质量是散落的针，段均值正好把针滤掉。这解释了为何它与稀疏选边、与块选择（后来的 NSA 一类）直觉相近却机制不同：它没有「展开某一块做满注意力」的第二阶段，只有一层低秩式重构。</p><p>因果化同样困难。段均值若包含未来 token，泄漏；若每段只用过去，地标集合随 \\(t\\) 变，伪逆每步都要更新，生成复杂度不再是简单的 \\(O(md)\\) 状态。原文主设定是编码器式双向。把 Nyströmformer 写进自回归服务前，必须先有合法的因果地标方案，不能只加下三角掩码。</p><p><span class="marginnote">LRA 上的赢面常常来自「能跑到更长」而不是「同长度下逼近误差更小」。报告应同时给出同 \\(n\\) 的满注意力对照（若显存允许）和更长 \\(n\\) 的稀疏/线性对照，否则不知道赢的是近似质量还是长度本身。</span></p><h3 id="地标质量决定误差" tabindex="-1">地标质量决定误差 <a class="header-anchor" href="#地标质量决定误差" aria-label="Permalink to &quot;地标质量决定误差&quot;">​</a></h3><p>\\(m\\) 不够，重构欠秩，头之间的细对齐消失。分段不齐（padding、文档边界跨段）会让地标语义混乱。训练足够久时，模型可能学会避开依赖精确对齐的解，改走 FFN，表面上任务分数可接受。下游若需要拷贝罕见标识符，应单独测，不要用 GLUE 平均分给 Nyström 背书。可学习地标或两阶段「先选后精算」已经超出 AAAI 2021 的默认层，属于后继工作。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>主场是用线性层替换编码器自注意力，并在当时的 LRA/GLUE 协议上展示可行性。它不是 FlashAttention 的竞品：Flash 算的是精确（分块）softmax，Nyström 算的是近似矩阵。今天短到中等 \\(n\\) 上，精确核往往又快又准，Nyström 的动机回到「\\(n\\) 大到精确也不想要 \\(n^2\\) 语义」的场景——但那种场景现在更多被滑窗、检索、分块选择占据。</p><p>实现陷阱：忘记对地标计算做 padding 掩码；伪逆在 fp16 下发散；把 segment-means 做成不可导的硬池化却仍期望端到端梯度（均值是可导的，硬选下标不是）。与 Reformer 的哈希桶、Routing 的 k-means 相比，段均值最盲、也最稳。盲是误差来源，稳是能先训起来的原因。</p><p><span class="marginnote">论文作者列表跨体系结构与系统（Keutzer、Stoica 等），提醒这是「算法近似 + 训得动」的系统工作。只抄公式、不抄稳定伪逆与地标方案，很容易得到一个理论上的线性层和一次实际的 NaN。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Nyströmformer 原文贡献是：用段均值等地标对 softmax 注意力做 Nyström 重构，并以迭代伪逆保证可训。</li><li>近似发生在 softmax 之后的矩阵结构上，与 Linformer 的预投影、Performer 的随机特征分工明确。</li><li>误差由地标是否张成真实注意力的主列空间决定；段均值会滤掉段内针。</li><li>主场是双向编码器；因果生成需要另写合法地标，不是加个掩码。</li><li>\\(m\\) 与墙钟、数值稳定性绑在同一旋钮上。</li><li>短 \\(n\\) 上精确注意力往往更可取；其历史位置是线性近似家族的一员。</li><li>出处：Xiong et al., <em>Nyströmformer: A Nyström-Based Algorithm for Approximating Self-Attention</em>, AAAI 2021。</li></ul>',16))])}const y=m(d,[["render",h]]);export{_ as __pageData,y as default};
